"""Explain mapping return contracts, header names and metadata ownership."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1869': ('결과 숫자는 함수마다 약속이 달라요. 어떤 함수는 true로 진행을 알리지만, 이 함수는 오류가 없을 때 0을 돌려줘요.', '정수 오류 반환과 결과 확인 표시를 이해합니다.', '반환값 0→이 단계에서 오류를 알리지 않음, 0 아님→오류 처리 확인이라는 두 길을 적으세요.', ['vmap은 여러 페이지를 연속된 가상 주소 범위에서 사용할 수 있게 연결하는 기능이에요. KMSAN의 vmap 도우미는 데이터에 딸린 검사 정보도 가상 주소 범위에 연결해요. 검사 정보에는 준비 상태인 shadow와 발생 원인인 origin이 있어요.', 'kmsan_vmap_pages_range_noflush의 반환 형식은 int, 즉 정수예요. 이 함수의 약속은 성공을 0으로, 오류를 0이 아닌 값으로 알리는 것이에요. 앞의 memblock 함수가 true로 진행 가능 상태를 알린 것과 같은 방식으로 외우면 안 돼요.', '선언에 붙은 __must_check는 결과를 무시하지 말라는 표시예요. 컴파일러가 잘못된 사용을 경고하도록 돕지만, 이 표시 자체가 오류를 처리하거나 실패한 연결을 자동으로 되돌리는 것은 아니에요.', '검사 기능을 넣은 구현에서는 필요한 준비나 연결이 실패하면 오류를 전달해요. 호출자는 그 값을 확인하고 자기 작업의 실패 처리를 이어가야 해요. 이름에 성공이라는 말이 없어도 선언과 구현의 반환 약속을 함께 읽어요.', 'CONFIG_KMSAN을 넣지 않은 빌드의 대체 함수는 작업 없이 0을 반환해요. 검사 기능이 켜진 구현에도 kmsan_enabled가 꺼져 있으면 0으로 돌아가는 길이 있어요. 그래서 0만 보고 검사 정보가 반드시 새로 연결됐다고 단정할 수는 없어요.', '또 이 도우미의 결과는 실제 데이터 페이지 연결 전체의 성공 보증이 아니에요. 호출하는 쪽에는 데이터 연결 작업과 그 결과도 있어요. 하나의 준비 단계가 오류를 알리지 않았다는 것과 전체 작업 완료를 구별하세요.'], [('이 정수 반환 mapping 도우미의 성공 값은 무엇인가요?', ['언제나 true를 뜻하는 1이에요', '0이에요'], '정답은 두 번째예요. 이 API는 0을 성공 값으로 사용하는 약속이에요. 작업을 생략하는 대체 함수도 0이므로 실제로 한 작업은 설정과 분기를 함께 확인해야 해요.'), ('__must_check는 어떤 사용을 요구하나요?', ['호출 뒤 반환 결과를 확인해야 해요', '인자 이름을 반드시 바꿔야 해요'], '정답은 첫 번째예요. 오류를 무시한 채 다음 작업을 계속하지 않도록 결과 확인을 요구하는 표시예요. 인자 이름 변경이나 자동 복구를 뜻하지 않아요.')]), 'os1870': ('설명표의 이름과 실제 문에 붙은 이름이 다르면 문 번호를 확인해야 해요. 코드에서도 주석과 실제 함수 선언을 함께 봐요.', '설명 주석의 이름과 실제 호출 가능한 선언을 대조합니다.', '주석 kmsan_map_kernel_range_noflush 옆에 실제 선언 kmsan_vmap_pages_range_noflush를 나란히 적으세요.', ['헤더는 다른 파일에서 사용할 함수 이름과 인자 형식을 알려 주는 파일이에요. 주석은 사람이 읽는 설명이고, 선언은 컴파일러가 함수 호출 형태를 확인할 때 사용하는 코드예요.', '이 고정된 Linux v6.12 헤더의 설명 제목에는 kmsan_map_kernel_range_noflush라는 이름이 있어요. 하지만 바로 아래 실제 선언 이름은 kmsan_vmap_pages_range_noflush예요. 비슷해 보여도 철자가 다른 이름이에요.', '연결을 해제하는 설명도 마찬가지예요. 주석에는 kmsan_vunmap_kernel_range_noflush라고 쓰여 있고 실제 선언은 kmsan_vunmap_range_noflush예요. 주석의 이름이 있다고 그 이름의 함수가 자동으로 만들어지지는 않아요.', '호출을 이해할 때는 실제 선언 이름으로 구현 본문을 찾아야 해요. vmap 도우미 본문은 shadow.c, vunmap 도우미 본문은 hooks.c에 있어요. 이렇게 선언과 구현을 연결하면 어느 코드를 실행하는지 확인할 수 있어요.', '주석은 필요한 배경과 사용 조건을 알려 주지만 코드와 이름이 어긋난 부분이 남을 수 있어요. 이를 보고 없는 함수를 새로 추측하거나 두 이름이 언제나 같은 별명이라고 가정하지 않아요.', '이 수업은 프로젝트가 고정한 버전의 실제 불일치를 읽는 연습이에요. 다른 버전까지 항상 같은 이름이라고 외우기보다 사용하는 소스의 선언·구현·호출부를 함께 확인하는 습관을 익히세요.'], [('이 헤더에서 실제로 선언한 공개 vmap 함수 이름은 무엇인가요?', ['주석에 적힌 kmsan_map_kernel_range_noflush만 실제 함수예요', 'kmsan_vmap_pages_range_noflush예요'], '정답은 두 번째예요. 주석 아래 int로 시작하는 선언을 읽으면 확인할 수 있어요. 주석의 설명 이름과 실제 코드 이름을 구별하세요.'), ('주석 이름과 선언 이름이 다르면 어떻게 확인하나요?', ['실제 선언 이름으로 구현과 호출부를 대조해요', '주석에 있으니 그 이름의 새 함수가 반드시 있다고 생각해요'], '정답은 첫 번째예요. 주석은 실행할 함수를 정의하지 않아요. 실제 선언과 구현을 연결해야 사용할 이름과 동작을 확인할 수 있어요.')]), 'os1871': ('이미 있는 점검표를 새 주소로 연결하는 일과 새 점검표를 만드는 일은 달라요. 나중에 연결을 풀 때도 누가 만든 물건인지 알아야 해요.', 'vmap과 ioremap의 검사 정보 소유 방식, 설명과 검증의 차이를 이해합니다.', 'vmap은 기존 점검표→주소 연결, ioremap은 새 점검표 만들기→주소 연결로 두 줄을 그리세요.', ['mapping은 어떤 주소에서 실제 메모리를 찾아갈 수 있게 연결하는 일이에요. KMSAN은 데이터 주소뿐 아니라 준비 상태와 발생 원인을 담은 검사 정보 주소도 연결해요.', '일반 vmap 도우미는 전달받은 페이지들의 기존 shadow·origin 페이지를 연속된 가상 주소 범위에 연결해요. 주소 연결을 준비할 임시 포인터 배열은 만들지만, 이를 모든 검사 정보 페이지를 새로 만드는 일과 혼동하면 안 돼요.', 'ioremap 도우미는 새 shadow·origin 페이지를 할당해 연결해요. 원문 주석은 물리 페이지에 기존 검사 정보가 있더라도 이 경로에서는 그것을 무시한다고 설명해요. 두 함수가 이름만 다른 동일 작업은 아니에요.', '공개 설명은 iounmap에서 연결을 풀고 이 경로가 만든 검사 정보 페이지도 해제한다고 말해요. 일반 vunmap에서 기존 검사 정보의 주소 연결만 푸는 경우와 자원 소유 책임이 달라요. 연결 해제와 실제 페이지 해제는 별도 작업이에요.', '하지만 설명에 해제한다고 적혀 있다고 모든 실패 경로가 완벽하게 정리됐다는 증거가 되지는 않아요. 어디까지 할당했는지, 연결에 실패했는지, 어느 포인터가 남았는지에 따라 실행하는 분기가 달라져요.', '이 고정 구현의 iounmap은 현재 위치의 페이지를 조회한 뒤 그 위치부터 끝까지 연결을 풀어요. 다음 반복의 조회는 이미 풀린 연결을 만날 수 있어요. 따라서 문서의 의도와 실제 정리 범위를 따로 확인해야 하며 이 수업이 모든 오류·정리 경로의 완전한 검증을 뜻하지는 않아요.'], [('일반 vmap과 ioremap은 검사 정보 페이지를 소유하는 방식이 같나요?', ['네. 둘 다 무조건 모든 검사 정보 페이지를 새로 만들어요', '아니요. 기존 페이지 연결과 새 검사 정보 생성이라는 차이가 있어요'], '정답은 두 번째예요. 기존 자료의 주소 연결을 추가하는 것과 새 자료를 할당하는 것은 달라요. 그래서 나중에 무엇을 해제할지도 같은 것으로 가정할 수 없어요.'), ('iounmap 설명에 해제한다고 쓰여 있으면 모든 오류 경로의 정리가 검증된 건가요?', ['아니요. 실제 분기와 호출자, 할당·조회·해제 범위를 확인해야 해요', '네. 설명 한 줄로 모든 실패의 완전 복구가 증명돼요'], '정답은 첫 번째예요. 문서는 기대하는 역할을 설명해요. 실제 실행이 어느 자원까지 다루는지 증명하려면 코드의 경로와 필요한 실행 증거를 함께 봐야 해요.')]), 'os1872': ('공책 내용을 복사하는 일과 공책의 검사표를 맞추는 일은 달라요. 이 함수는 페이지의 내용보다 검사 상태를 맞추는 역할을 해요.', '복사 대상의 검사 정보 유무에 따른 처리와 데이터 복사의 차이를 이해합니다.', '출발 검사표 있음→검사표 복사, 출발 검사표 없음·도착 검사표 있음→도착을 준비됨으로 표시라는 두 길을 그리세요.', ['kmsan_copy_page_meta의 src는 출발 페이지, dst는 도착 페이지예요. meta는 데이터를 검사하는 데 사용하는 별도 정보예요. 함수 이름의 copy가 실제 데이터 페이지 내용 전체를 복사한다는 뜻은 아니에요.', '활성 구현은 먼저 검사가 꺼져 있거나 내부 검사 작업 중이면 돌아가요. 이 입구 조건을 통과한 다음에도 dst가 없거나 도착 페이지에 검사 정보가 없으면 아무 작업 없이 돌아가요.', '도착에는 검사 정보가 있지만 src가 없거나 출발에 검사 정보가 없으면, 도착 페이지 한 장의 검사 정보를 unpoison해 준비됨으로 표시해요. 출발의 실제 데이터를 0으로 지우는 것이 아니에요.', '이것은 추적하지 않는 출발 페이지를 다루는 정책이에요. 출발의 모든 실제 값이 올바르게 초기화됐다는 사실을 이 함수가 검사해 증명했다는 뜻은 아니에요. 실제 내용과 추적 상태를 구별해야 해요.', '양쪽에 검사 정보가 있으면 도착 shadow에 출발 shadow를, 도착 origin에 출발 origin을 각각 PAGE_SIZE만큼 복사해요. PAGE_SIZE는 이 환경의 한 페이지 바이트 수예요. 내부 작업 시작·끝 표시 사이에서 검사 정보 두 종류를 복사해요.', 'CONFIG_KMSAN이 없는 빌드의 같은 이름 대체 함수는 빈 본문이에요. 검사 정보 복사도 실제 데이터 복사도 하지 않아요. 호출하는 다른 코드가 맡은 데이터 복사와 이 검사 도우미의 역할을 나누어 읽으세요.'], [('입구 조건을 통과했고 src에는 검사 정보가 없지만 dst에는 있다면 무엇을 하나요?', ['출발 데이터 전체를 반드시 0으로 지워요', '도착 검사 정보를 unpoison해 준비됨으로 표시해요'], '정답은 두 번째예요. 검사 정보 없는 출발을 다루는 추적 정책이에요. 도착 검사표를 바꾸는 일은 출발 데이터 지우기나 실제 초기화 검증과 달라요.'), ('설정을 끈 빈 copy_page_meta 대체 함수가 실제 데이터 페이지를 복사하나요?', ['아니요. 빈 검사 도우미이며 데이터 복사는 다른 코드의 일이에요', '네. 모든 실제 페이지 복사를 대신해요'], '정답은 첫 번째예요. 이름에 copy가 있어도 대체 본문은 비어 있어요. 활성 구현도 여기서는 shadow와 origin이라는 검사 정보 복사를 맡아요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_463.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
